// Text with names in it (tracks, cars, drivers, setups): the words around the name are translated, the name kept.
// [regular expression source, replacement]. Used by i18n.js when a sentence isn't in the dictionary.
(() => {
  const D = () => window.GRID_ES || {};
  const tr = text => {
    const d = D();
    if (d[text] !== undefined) return d[text];
    const numbers = [];
    const key = text.replace(/\d+(?:[.:,]\d+)*/g, m => (numbers.push(m), "{#}"));
    if (d[key] === undefined) return text;
    let i = 0;
    return d[key].replace(/\{#\}/g, () => numbers[i++] ?? "");
  };
  const sentences = text => text.trim() ? text.trim().split(/(?<=[.!?])\s+/).map(s => (/[A-Za-z]{2}/.test(s) ? tr(s) : s)).join(" ") : "";
  const SESSION = { Race: "Carrera", Practice: "Entrenamientos", Qualify: "Clasificación", "Lone Qualify": "Clasificación", "Open Qualify": "Clasificación", Warmup: "Calentamiento", "Offline Testing": "Pruebas", Session: "Sesión", Testing: "Pruebas" };
  const AREA = { braking: "la frenada", "corner exit": "la salida de curva", "apex speed": "la velocidad en el vértice", coasting: "la inercia", "exit speed": "la velocidad de salida", line: "la trazada" };
  const AREA_TITLE = { Braking: "Frenada", "Corner exit": "Salida de curva", "Apex speed": "Velocidad en el vértice", Coasting: "Inercia", "Exit speed": "Velocidad de salida", Line: "Trazada", "Keep it up": "Sigue así" };
  const corner = name => name.replace(/\b(?:Turn|Corner) (\S+)/g, "curva $1");
  window.GRID_ES_PATTERNS = [
    // Phone pit wall and team hub (before "... is next." below).
    [String.raw`^Driver change at this stop: (.+) is next\.$`, "Cambio de piloto en esta parada: el siguiente es $1."],
    [String.raw`^Sent: “(.*)”$`, "Enviado: “$1”"],
    [String.raw`^(.+)\. Your car is the big dot\. Cars in the pits are faded\.$`, "$1. Tu coche es el punto grande. Los coches en boxes aparecen atenuados."],
    [String.raw`^Automatic pit fuel: (.+)\.$`, "Combustible automático en boxes: $1."],
    [String.raw`^Tread left \(inside/middle/outside %\): (.+)\. Measured when you were last in the pits\.$`, "Banda restante (interior/centro/exterior %): $1. Medida la última vez que pasaste por boxes."],
    [String.raw`^On (.+) tyres, (\d+) laps? old\.$`, (m, compound, laps) => `Con neumáticos ${compound}, de ${laps} ${laps === "1" ? "vuelta" : "vueltas"}.`],
    [String.raw`^On (.+) tyres\.$`, "Con neumáticos $1."],
    [String.raw`^Last measured: (.+)\.$`, "Última medición: $1."],
    [String.raw`^scene: (.+)$`, "escena: $1"],
    [String.raw`^Couldn't do that: (.+)$`, (m, rest) => `No se ha podido hacer: ${sentences(rest)}`],
    [String.raw`^(✓ )?(?:Turn|Corner) (\S+)$`, (m, tick, name) => `${tick || ""}Curva ${name}`],
    [String.raw`^· (Braking|Corner exit|Apex speed|Coasting|Exit speed|Line)$`, (m, area) => `· ${AREA_TITLE[area]}`],
    // Race strategy: where you'd rejoin.
    [String.raw`^About <strong>([\d.]+) s</strong> lost(?:, rejoining around <strong>P(\d+)</strong>(?: \(P(\d+) now\))?)?\.(.*)$`, (m, loss, p, now, rest) =>
      `Unos <strong>${loss} s</strong> perdidos${p ? `, saliendo hacia <strong>P${p}</strong>${now ? ` (P${now} ahora)` : ""}` : ""}.${rest.replace(" Ahead: ", " Delante: ").replace(" Behind: ", " Detrás: ")}`],
    [String.raw`^From iRacing: (.+) at (.+?)\. (.*)$`, (m, car, track, rest) => `Desde iRacing: ${car} en ${track}. ${sentences(rest)}`],
    // Session debrief.
    [String.raw`^(Race|Practice|Qualify|Lone Qualify|Open Qualify|Warmup|Offline Testing|Testing|Session) at (.+): (\d+) laps(?:, best ([\d:.]+))?\.$`, (m, type, track, laps, best) =>
      `${SESSION[type] || type} en ${track}: ${laps} vueltas${best ? `, mejor ${best}` : ""}.`],
    [String.raw`^Your best (?:was ([\d.]+ s) (quicker|slower) than|matched) last time here \(([\d:.]+) on (.+)\)\.$`, (m, diff, way, time, date) =>
      diff ? `Tu mejor vuelta fue ${diff} ${way === "quicker" ? "más rápida" : "más lenta"} que la última vez aquí (${time} el ${date}).` : `Igualaste tu mejor vuelta de la última vez aquí (${time} el ${date}).`],
    [String.raw`^Most of your time goes at (.+)\.$`, (m, list) => `La mayor parte de tu tiempo se va en ${list.split("; ").map(item => item.replace(/^(?:Turn|Corner) (\S+)(?: \(([^)]+)\))?, ([\d.]+) s a lap$/, (x, n, area, s) => `la curva ${n}${area ? ` (${(AREA[area] || area).replace(/^la /, "")})` : ""}, ${s} s por vuelta`)).join("; ")}.`],
    [String.raw`^You fixed (.+) this session\.(.*)$`, (m, list, rest) => `Corregiste ${corner(list).replace(" and ", " y ")} esta sesión.${rest ? ` ${sentences(rest)}` : ""}`],
    [String.raw`^Next time: work on (?:Turn|Corner) (\S+?)(?:, ([a-z ]+))?\.(.*)$`, (m, n, area, rest) => `La próxima vez: trabaja la curva ${n}${area ? `, ${AREA[area] || area}` : ""}.${rest ? ` ${sentences(rest)}` : ""}`],
    [String.raw`^(Finished|Left the race in) P(\d+)(.*)$`, (m, how, p, rest) => `${how === "Finished" ? "Terminaste" : "Abandonaste la carrera en"} P${p}${rest.replace(/^ from P(\d+)/, " desde P$1").replace(/\. (.*)$/, (x, more) => `. ${tr(more)}`)}`],
    // Coaching with corner names (Turn 5a, Corner 3).
    [String.raw`^(?:<b>)?(?:Turn|Corner) (\S+?)(?:</b>)? · (.+)$`, (m, n, area) => `${m.startsWith("<b>") ? `<b>Curva ${n}</b>` : `Curva ${n}`} · ${AREA_TITLE[area] || area}`],
    [String.raw`^Focus on <strong>(?:Turn|Corner) (\S+) · ([^<]+)</strong>\. (.*)$`, (m, n, area, rest) => `Céntrate en <strong>curva ${n} · ${AREA_TITLE[area] || area}</strong>. ${sentences(rest)}`],
    [String.raw`^You're giving away <strong>([\d.]+)s in (?:Turn|Corner) (\S+)</strong>\. (.*)$`, (m, s, n, rest) => `Estás perdiendo <strong>${s}s en la curva ${n}</strong>. ${sentences(rest)}`],
    [String.raw`^(?:Turn|Corner) (\S+?) sorted\.$`, (m, n) => `Curva ${n} resuelta.`],
    [String.raw`^New focus: (?:Turn|Corner) (\S+?)\.$`, (m, n) => `Nueva curva clave: curva ${n}.`],
    [String.raw`^(?:Turn|Corner) (\S+?) next\.$`, (m, n) => `Ahora la curva ${n}.`],
    [String.raw`^(?:Turn|Corner) (\S+?): (.+)\.$`, (m, n, what) => {
      const NUMBERS = { two: "dos", three: "tres", four: "cuatro", five: "cinco", six: "seis", seven: "siete", eight: "ocho", nine: "nueve" };
      const way = w => (w === "better" ? "mejor" : "más lento");
      const words = what.replace(/^matched your best$/, "igual que tu mejor").replace(/^a few hundredths (better|slower)$/, (x, w) => `unas centésimas ${way(w)}`)
        .replace(/^a tenth (better|slower)$/, (x, w) => `una décima ${way(w)}`).replace(/^(\w+) tenths (better|slower)$/, (x, t, w) => `${NUMBERS[t] || t} décimas ${way(w)}`);
      if (words !== what) return `Curva ${n}: ${words}.`;
      const advice = tr(what.charAt(0).toUpperCase() + what.slice(1) + ".").replace(/\.$/, "");
      return `Curva ${n}: ${advice.charAt(0).toLowerCase() + advice.slice(1)}.`;
    }],
    // Spoken hazards and damage.
    [String.raw`^(Car stopped ahead|Slow car ahead|Car off ahead|Hazard ahead), (?:Turn|Corner) (\S+?)\.$`, (m, what, n) => `${tr(what + ".").replace(/\.$/, "")}, curva ${n}.`],
    [String.raw`^Damage, probably (front|front right|right side|rear right|rear|rear left|left side|front left)\.$`, (m, zone) =>
      `Daños, probablemente ${{ front: "delante", "front right": "delante a la derecha", "right side": "en el lado derecho", "rear right": "detrás a la derecha", rear: "detrás", "rear left": "detrás a la izquierda", "left side": "en el lado izquierdo", "front left": "delante a la izquierda" }[zone]}.`],
    [String.raw`^from P(\d+)(.*)$`, (m, p, rest) => `desde P${p}${rest}`],
    [String.raw`^YOUR NOTES ON (.+)$`, (m, name) => `TUS NOTAS DE ${name}`],
    [String.raw`^Lap (\d+) matched your best lap in every corner\. Nice and consistent\.$`, (m, n) => `La vuelta ${n} igualó tu mejor vuelta en todas las curvas. Muy regular.`],
    [String.raw`^no change since (.+)$`, (m, date) => `sin cambios desde el ${date}`],
    [String.raw`^Couldn't load the lap library \((.+)\)\.$`, (m, why) => `No se pudo cargar la biblioteca de vueltas (${why === "the library has no index.json yet" ? "la biblioteca aún no tiene index.json" : why}).`],
    [String.raw`^You were faster here than on your best lap\. Whatever you did through (?:Turn|Corner) (\S+), repeat it\.$`, (m, n) => `Aquí fuiste más rápido que en tu mejor vuelta. Lo que hicieras en la curva ${n}, repítelo.`],
    // Names in the setup and lap pages.
    [String.raw`^(.+) \(loaded now\)$`, (m, name) => `${name} (cargado ahora)`],
    [String.raw`^Here \((.+)\)$`, (m, track) => `Aquí (${track})`],
    [String.raw`^At (.+)$`, (m, track) => `En ${track}`],
    [String.raw`^iRacing track map of (.+)$`, (m, track) => `Mapa de iRacing de ${track}`],
    [String.raw`^Track map of (.+)$`, (m, track) => `Mapa de ${track}`],
    [String.raw`^No (.+) template found in the templates folder\. Drop one here, or use Load template\.$`, (m, car) => `No se ha encontrado ninguna plantilla de ${car} en la carpeta templates. Suelta una aquí o usa Cargar plantilla.`],
    [String.raw`^Grid Central has seen one setup for this car \((.+)\)\. Load another in iRacing's garage and it'll be here to compare\.$`, (m, name) => `Grid Central ha visto un reglaje de este coche (${name}). Carga otro en el garaje de iRacing y aparecerá aquí para compararlo.`],
    [String.raw`^(.+?) <small>on (.+)</small>$`, (m, title, setup) => `${tr(title)} <small>con ${setup}</small>`],
    [String.raw`^Heads up, you're on a qualifying setup, (.+)\. Check the fuel and the tyre pressures\.$`, (m, name) => `Atención, llevas un reglaje de clasificación, ${name}. Revisa el combustible y las presiones.`],
    [String.raw`^Driver change, (.+) is next\.$`, (m, name) => `Cambio de piloto, el siguiente es ${name}.`],
    [String.raw`^(.+) is next\.$`, (m, name) => `El siguiente es ${name}.`],
    [String.raw`^(.+) says: (.+)$`, (m, name, text) => `${name} dice: ${text}`],
    [String.raw`^Notes on (.+?): (.+)$`, (m, name, text) => `Notas de ${name}: ${text}`],
    [String.raw`^Coaching against (.+?)'s ([\d:.]+)\. Your laps are now compared with it on the AI spotter page\.$`, (m, who, time) => `Entrenando contra la vuelta de ${who} (${time}). Tus vueltas se comparan ahora con ella en la página del Spotter IA.`],
    [String.raw`^(.+?)'s lap · coaching against it$`, (m, who) => `Vuelta de ${who} · entrenando contra ella`],
    [String.raw`^Track is (getting wetter|drying), (.+) now\.$`, (m, how, level) => `La pista se está ${how === "drying" ? "secando" : "mojando más"}, ahora ${tr(level)}.`]
  ];
})();
